patches.content:
// screentime: the stock unused list is built from the hardcoded
// availableToggleTypes, so once this tile is removed in edit mode
// it could never be re-added from the UI. Offer it here whenever
// it is absent from the config.
ButtonGroup {
    visible: !root.toggles.some(t => t && t.type === "screentime")
    spacing: root.spacing

    Repeater {
        model: ScriptModel {
            values: root.toggles.some(t => t && t.type === "screentime") ? [] : [{ type: "screentime", size: 1 }]
            objectProp: "type"
        }
        delegate: AndroidToggleDelegateChooser {
            startingIndex: -1
            editMode: root.editMode
            baseCellWidth: root.baseCellWidth
            baseCellHeight: root.baseCellHeight
            spacing: root.spacing
        }
    }
}
